package holamundo;

public class Condicionales {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int x = 7;
        int y = (x < 10) ? x * 2 : x - 3;
         
        System.out.println("Valor de x es: " + x);
        System.out.println("Resultado de y es: " + y);
    }
}

	
